            ds.valueHistory = []; ds.targetHistory = []; ds.riskHistory = []; ds.npsHistory = []; ds.cmpHistory = [];
            var rs = null;
            for (i = 1; i <= period; i++) {
                var r = this._roundScore(state, i);
                var o = r.o;
                ds.valueHistory[i - 1] = Math.round(o.value * 1000);
                ds.targetHistory[i - 1] = Math.round(o.target * 10) / 10;
                ds.riskHistory[i - 1] = Math.round(o.risk * 1000);
                ds.npsHistory[i - 1] = Math.round(o.nps);
                ds.cmpHistory[i - 1] = Math.round(o.cmp);
                if (i === period) { rs = r; }
            }
            var ow = rs.o;
            ds.roundScores[period - 1] = rs.score;
            ds.scoreHistory[period - 1] = rs.score;
            ds.breach = ow.breach;
            ds.last = { roundScore: rs.score, value: Math.round(ow.value * 1000), target: Math.round(ow.target * 10) / 10,
                        risk: Math.round(ow.risk * 1000), nps: Math.round(ow.nps), cmp: Math.round(ow.cmp) };
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.value = ds.last.value;
            out.target = ds.last.target;
            out.risk = ds.last.risk;
            out.nps = ds.last.nps;
            out.cmp = ds.last.cmp;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _complete(dec, period) {
            var out = {};
            var p, i, key, v;
            for (p = 1; p <= 4; p++) {
                var keys = (this.CONTROLS[p] || []).map(function(g) { return g + p; });
                for (i = 0; i < keys.length; i++) {
                    key = keys[i];
                    if (p <= period) {
                        v = dec[key];
                        out[key] = (v === undefined || v === null) ? this.DEFAULTS[key] : v;
                    } else {
                        out[key] = (this.REF[key] !== undefined) ? this.REF[key] : this.DEFAULTS[key];
                    }
                }
            }
            return out;
        }

        _run(d) {
            var c = this.C;
            var eq = this.EQ[d.equipo1];
            var A = eq[0], P = eq[1], R = eq[2];
            var pf = 0.8 + 0.5 * P;
            var rf = R / 0.20;
            var nps = c.NPS0 + eq[3];
            var cmp = c.CMP0;
            var h1 = d.hipoteca1;
            var inc = d.incentivo4;
            var prodF = 1.0 + this.INC_PROD[inc];
            var H = c.H0 * Math.sqrt(A / c.A_REF) * this.HV[h1] * prodF;
            var niiH = H * this.HS[h1];
            var reprice = (h1 === 'rebaja') ? c.BACK * c.REPRICE * c.CUT : 0.0;
            var elH = H * this.PDH[h1] * c.LGD_H;
            var pols = H / c.AVG_H * this.HA[h1];
            nps += this.H_NPS[h1];
            cmp += this.H_CMP[h1];
            var loss = this.H_LOSS[h1];
            var ca = d.cartera2;
            var cp = this.CP[ca] * pf * prodF;
            var niiC = cp * c.CS;
            var elC = cp * this.PDC[ca] * c.LGD_C;
            var fees = c.BASE_FEES + this.CART_FEES[ca] * pf;
            var ins = c.INS_B * pf + this.CART_INS[ca];
            var funds = c.FB * pf + this.CART_FUNDS[ca];
            nps += this.CART_NPS[ca];
            cmp += this.CART_CMP[ca];
            if (ca === 'grandes') { loss += this.GRANDES_LOSS * (1.0 - 0.5 * Math.min(1.0, rf)); }
            var de = d.deposito2;
            var ar = c.AR;
            var depV, retained;
            if (de === 'fondos') {
                var stay = Math.min(1.0, c.FSTAY * pf);
                var moved = c.FM;
                var lost = Math.max(0.0, 1.0 - stay - moved);
                depV = -ar * (moved + lost) * c.DM + ar * moved * c.FF;
                funds += ar * moved;
                if (R < 0.15) { cmp += this.FONDOS_LOWR_CMP; }
                retained = stay + moved;
            } else {
                var r = Math.min(1.0, this.R0[de] * pf);
                depV = -ar * (1.0 - r) * c.DM;
                if (de === 'selectivo') {
                    depV -= ar * r * c.BONUS_SH * c.BONUS;
                } else if (de === 'todos') {
                    depV -= c.DEP * c.ALL_UP;
                }
                retained = r;
            }
            fees -= this.LOST_FEES * (1.0 - retained);
            nps += this.DEP_NPS[de];
            cmp += this.DEP_CMP[de];
            var mo = d.mora3;
            var lr = (mo === 'temprana') ? c.ARR_LR * (1.0 - c.EARLY * Math.min(1.0, rf)) : this.MORA_LR[mo];
            var arr = c.ARR * lr + this.MORA_X[mo];
            nps += this.MORA_NPS[mo];
            cmp += this.MORA_CMP[mo];
            var find = this.MORA_FIND[mo];
            var ky = d.kyc3;
            var breach = (ky === 'avisar');
            loss += this.KYC_LOSS[ky];
            fees += this.KYC_FEES[ky];
            nps += this.KYC_NPS[ky];
            ins += this.INC_INS[inc];
            nps += this.INC_NPS[inc];
            cmp += this.INC_CMP[inc];
            loss += this.INC_LOSS[inc];
            var ci = d.cierre4;
            fees += this.CIE_FEES[ci];
            ins += this.CIE_INS[ci];
            var hExtra = this.CIE_H[ci];
            niiH += hExtra * this.CIE_HS;
            reprice += c.BACK * this.CIE_REPRICE[ci] * c.CUT;
            elH += hExtra * this.PDH.tabla * c.LGD_H;
            var hAll = H + hExtra;
            nps += this.CIE_NPS[ci];
            cmp += this.CIE_CMP[ci];
            loss += this.CIE_LOSS[ci];
            ins += pols;
            var risk = elH + elC + arr + loss + find;
            var value = c.BASE_NII_H + niiH - reprice + c.DEP * c.DM + depV + niiC + fees
                - c.COST - c.BASE_PROV - elH - elC - arr - loss - find;
            var tm = Math.min(c.TCAP, hAll / c.TH);
            var tc = Math.min(c.TCAP, cp / c.TC);
            var ti = Math.min(c.TCAP, ins / c.TI);
            var tf = Math.min(c.TCAP, funds / c.TF);
            var target = 100.0 * (0.40 * tm + 0.20 * tc + 0.20 * ti + 0.20 * tf);
            nps = this._clamp(nps, -100.0, 100.0);
            cmp = Math.max(0.0, cmp);
            return { value: value, target: target, risk: risk, nps: nps, cmp: cmp, H: hAll, cp: cp, ins: ins, funds: funds,
                     retained: retained, breach: breach, pf: pf, rf: rf };
        }

        _components(o) {
            var c = this.C;
            return {
                v: this._clamp((o.value - c.V_LO) / (c.V_HI - c.V_LO), 0, 1),
                t: this._clamp((o.target - c.T_LO) / (c.T_HI - c.T_LO), 0, 1),
                k: this._clamp((c.K_HI - o.risk) / (c.K_HI - c.K_LO), 0, 1),
                n: this._clamp((o.nps - c.N_LO) / (c.N_HI - c.N_LO), 0, 1),
                r: this._clamp((c.R_HI - o.cmp) / (c.R_HI - c.R_LO), 0, 1)
            };
        }

        _cap(o) {
            var m = this._components(o);
            return Math.max(this.C.CAP_FLOOR, this.C.CAP_BASE - this.C.CAP_K * (1.0 - 0.5 * (m.n + m.r)));
        }

        _roundScore(state, period) {
            var c = this.C;
            var d = this._complete(this._flat(state, period), period);
            var o = this._run(d);
            var m = this._components(o);
            var W = c.W_V + c.W_T + c.W_K + c.W_N + c.W_R;
            var score = 100.0 * (c.W_V * m.v + c.W_T * m.t + c.W_K * m.k + c.W_N * m.n + c.W_R * m.r) / W;
            score = this._clamp(score, 0, 100);
            if (o.breach) { score = Math.min(score, this._cap(o)); }
            return { score: this._jsround(score), o: o, d: d };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                num += w[p - 1] * this._roundScore(state, p).score;
                den += w[p - 1];
            }
            var total = this._clamp(this._jsround(num / den), 0, 100);
            var o = this._run(this._complete(this._flat(state, n), n));
            if (o.breach) { total = Math.min(total, this._jsround(this._cap(o))); }
            return total;
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtNum(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'es') ? '.' : ',';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 ? '-' : '') + out;
        }

        _fmtEur(n) {
            var body = this._fmtNum(n);
            return (this._lang() === 'es') ? (body + ' €') : (body.charAt(0) === '-' ? '-€' + body.slice(1) : '€' + body);
        }

        _one(n) {
            var s = (Math.round(n * 10) / 10).toFixed(1);
            if (this._lang() === 'es') { s = s.replace('.', ','); }
            return s;
        }

        _pct(n) {
            return (this._lang() === 'es') ? (String(n) + ' %') : (String(n) + '%');
        }

        _pctOne(n) {
            return (this._lang() === 'es') ? (this._one(n) + ' %') : (this._one(n) + '%');
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(g) {
                var el = document.getElementById(g + period);
                if (el && k[g + period]) { el.value = k[g + period]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var vH = ds.valueHistory || [];
            var tH = ds.targetHistory || [];
            var kH = ds.riskHistory || [];
            var nH = ds.npsHistory || [];
            var cH = ds.cmpHistory || [];
            var n = vH.length;
            this._set('valueDisplay', n ? this._fmtEur(vH[n - 1]) : '-');
            this._set('metDisplay', n ? (this._t('txt_target') + ' ' + this._pctOne(tH[n - 1]) + ' · ' + this._t('txt_risk') + ' ' + this._fmtEur(kH[n - 1])) : '-');
            this._set('credDisplay', n ? ('NPS ' + String(nH[n - 1]) + ' · ' + String(cH[n - 1]) + ' ' + this._t('txt_complaints')) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var d = this._complete(this._flat(state, p), p);
            var o = this._run(d);
            if (o.breach && p >= 3) { return this._t('hint_breach'); }
            if (p === 1 && d.equipo1 !== 'equilibrado' && d.equipo1 !== 'cartera') { return this._t('hint_equipo'); }
            if (p === 1 && d.hipoteca1 !== 'tabla') { return this._t('hint_hipoteca'); }
            if (p === 2 && d.cartera2 !== 'necesidades') { return this._t('hint_cartera'); }
            if (p === 2 && d.deposito2 !== 'selectivo') { return this._t('hint_deposito'); }
            if (p === 3 && d.mora3 !== 'temprana') { return this._t('hint_mora'); }
            if (p === 3 && d.kyc3 !== 'comunicar') { return this._t('hint_kyc'); }
            if (p === 4 && d.incentivo4 !== 'cuadro') { return this._t('hint_incentivo'); }
            if (p === 4 && d.cierre4 === 'empujar') { return this._t('hint_cierre'); }
            return null;
        }

        getChartConfig() {
            return {
                valueChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Objetivo comercial (%)', data: [], borderColor: '#1f5c47', backgroundColor: 'rgba(31,92,71,0.12)', borderWidth: 2 },
                            { label: 'NPS', data: [], borderColor: '#7a3b12', backgroundColor: 'rgba(122,59,18,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true } } }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Puntuación de la ronda', data: [], borderColor: '#1f5c47', backgroundColor: 'rgba(31,92,71,0.35)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var targetHistory = ds.targetHistory || [];
            var npsHistory = ds.npsHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = targetHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                valueChart: {
                    labels: labels,
                    datasets: [
                        { data: targetHistory.slice(), label: this._t('chart_target') },
                        { data: npsHistory.slice(), label: this._t('chart_nps') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var eur = function(v) { return self._fmtEur(v); };
            var pctOne = function(v) { return self._pctOne(v); };
            return [
                { key: 'results.value', label: 'Contribución de la oficina 2027', i18nKey: 'col_value', formatter: eur },
                { key: 'results.target', label: 'Objetivo comercial', i18nKey: 'col_target', formatter: pctOne },
                { key: 'results.risk', label: 'Coste del riesgo y del cumplimiento', i18nKey: 'col_risk', formatter: eur },
                { key: 'results.nps', label: 'NPS', i18nKey: 'col_nps' },
                { key: 'results.cmp', label: 'Reclamaciones', i18nKey: 'col_cmp' },
                { key: 'results.roundScore', label: 'Puntuación de la ronda', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var m = Math.max(1, n);
            var d = this._complete(this._flat(state, m), m);
            var o = this._run(d);
            var composite = this._composite(state);
            var insights = [];
            insights.push(this._t({ equilibrado: 'fb_eq_equilibrado', captacion: 'fb_eq_captacion', cartera: 'fb_eq_cartera', ventanilla: 'fb_eq_ventanilla' }[d.equipo1]));
            insights.push(this._t({ tabla: 'fb_hi_tabla', rebaja: 'fb_hi_rebaja', obligatorio: 'fb_hi_obligatorio', flexible: 'fb_hi_flexible' }[d.hipoteca1]));
            if (m >= 2) {
                insights.push(this._t({ necesidades: 'fb_ca_necesidades', preconcedidos: 'fb_ca_preconcedidos', dormidos: 'fb_ca_dormidos', grandes: 'fb_ca_grandes' }[d.cartera2]));
                insights.push(this._t({ selectivo: 'fb_de_selectivo', todos: 'fb_de_todos', nada: 'fb_de_nada', fondos: 'fb_de_fondos' }[d.deposito2]));
            }
            if (m >= 3) {
                insights.push(this._t({ temprana: 'fb_mo_temprana', esperar: 'fb_mo_esperar', agencia: 'fb_mo_agencia', maquillar: 'fb_mo_maquillar' }[d.mora3]));
                insights.push(this._t({ comunicar: 'fb_ky_comunicar', avisar: 'fb_ky_avisar', ignorar: 'fb_ky_ignorar', cerrar: 'fb_ky_cerrar' }[d.kyc3]));
            }
            if (m >= 4) {
                insights.push(this._t({ cuadro: 'fb_in_cuadro', volumen: 'fb_in_volumen', concurso: 'fb_in_concurso', fijo: 'fb_in_fijo' }[d.incentivo4]));
                insights.push(this._t({ valor: 'fb_ci_valor', empujar: 'fb_ci_empujar', rebajar: 'fb_ci_rebajar', aceptar: 'fb_ci_aceptar' }[d.cierre4]));
            }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                value: Math.round(o.value * 1000),
                target: Math.round(o.target * 10) / 10,
                risk: Math.round(o.risk * 1000),
                nps: Math.round(o.nps),
                cmp: Math.round(o.cmp),
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="suc1744-cm">'
                + '<div class="suc1744-cm-score">' + score + '<span class="suc1744-cm-max">/100</span></div>'
                + '<div class="suc1744-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="suc1744-cm-kpis">'
                + '<div class="suc1744-cm-kpi">' + this._t('cm_kpi_value') + ' <strong>' + this._fmtEur(s.value || 0) + '</strong></div>'
                + '<div class="suc1744-cm-kpi">' + this._t('cm_kpi_target') + ' <strong>' + this._pctOne(s.target || 0) + '</strong></div>'
                + '<div class="suc1744-cm-kpi">' + this._t('cm_kpi_risk') + ' <strong>' + this._fmtEur(s.risk || 0) + '</strong></div>'
                + '<div class="suc1744-cm-kpi">' + this._t('cm_kpi_nps') + ' <strong>' + String(s.nps || 0) + '</strong></div>'
                + '<div class="suc1744-cm-kpi">' + this._t('cm_kpi_cmp') + ' <strong>' + String(s.cmp || 0) + '</strong></div>'
                + '</div>'
                + '<div class="suc1744-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="suc1744-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getTranslations() {
            return {
        es: {
            btn_next: `Cerrar el trimestre`,
            cartera_dormidos: `Reactivar las cuentas dormidas, los saldos más baratos de recuperar`,
            cartera_grandes: `El producto estructurado del trimestre a los mayores depositantes`,
            cartera_necesidades: `Revisión de necesidades de los 150 clientes más vinculados: qué tienen y qué les falta`,
            cartera_preconcedidos: `La campaña de préstamos preconcedidos a todos los clientes que marca el sistema`,
            chart_nps: `NPS`,
            chart_score: `Puntuación de la ronda`,
            chart_target: `Objetivo comercial (%)`,
            cierre_aceptar: `Aceptar el hueco y no tocar nada, para proteger la cuenta de resultados`,
            cierre_empujar: `Añadir un seguro a cada operación que siga abierta en diciembre`,
            cierre_rebajar: `Bajar el diferencial hipotecario a 0,40 puntos para cerrar 1,5 millones más`,
            cierre_valor: `Una campaña sobre las necesidades ya detectadas, explicando el resto del hueco`,
            cm_debrief: `Lo que no decía la hoja de objetivos: una hipoteca a precio de tabla aporta un 0,90 % al año sobre su saldo, y cada euro de depósito que se queda aporta un 1,20 %. La base de la oficina era de 1.037.000 € al año; casi todo lo que decidisteis podía restarle más de lo que podía sumarle. La mejor jugada cumple el 89 % del objetivo y aporta 988.600 €; la que cumple el 112 % aporta 504.685 €.`,
            cm_kpi_cmp: `Reclamaciones`,
            cm_kpi_nps: `NPS`,
            cm_kpi_risk: `Riesgo y cumplimiento`,
            cm_kpi_target: `Objetivo comercial`,
            cm_kpi_value: `Contribución`,
